cat > spec/list_room.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" ] || { echo "list --room with another date should be empty"; fail=1; }
err=$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null); rc=$?
[ "$rc" = 2 ] || { echo "list --room without a value should exit 2"; fail=1; }
[ "$err" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without a value should print usage"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash spec/list_room.spec.sh && echo room-ok; bash spec/list_date.spec.sh && echo date-ok; bash spec/list.spec.sh && echo list-ok; bash spec/book.spec.sh && echo book-ok; bash spec/slots.spec.sh && echo slots-ok; echo ----; bash tools/check; echo "rc=$?"; bash tools/lint; echo "lint rc=$?"

